const input = $input.first().json.body || $input.first().json;

const callId = input.callId || `call_${Date.now()}`;
const agentName = input.agentName || input.salesRep || 'Unknown';
const customerName = input.customerName || input.customer || 'Unknown';
const transcript = input.transcript || '';
const duration = input.duration || input.durationMinutes || 0;
const audioUrl = input.audioUrl || '';

return {
  json: {
    callId,
    agentName,
    customerName,
    transcript,
    duration,
    audioUrl
  }
};

